#include "dma_generic.h"

/**********************************************************************************************************************
 * API IMPLEMENTATION
 **********************************************************************************************************************/

ACS_APP_VERSION_t DMA_GENERIC_GetAppVersion()
{
  ACS_APP_VERSION_t version;

  version.major = DMA_GENERIC_MAJOR_VERSION;
  version.minor = DMA_GENERIC_MINOR_VERSION;
  version.patch = DMA_GENERIC_PATCH_VERSION;

  return version;
}

DMA_GENERIC_STATUS_t DMA_GENERIC_Init(DMA_GENERIC_t *handle)
{
  if (handle == NULL)
  {
    return DMA_GENERIC_STATUS_FAILURE;
  }

  if (!handle->app_is_initialized)
  {
    handle->app_is_initialized = TRUE;

    IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, (handle->app_config != NULL));

    /* Initialize the DMA module with GUI configured parameters */
    IfxDma_Dma_initModule(handle->dma_handle, handle->app_config->lld_config);

    if (handle->app_config->sleep_config)
    {
      /* Enable DMA sleep mode as configured */
      IfxDma_setSleepMode(handle->dma_handle->dma, IfxDma_SleepMode_enable);
    }
    else
    {
      /* Disable DMA sleep mode as configured */
      IfxDma_setSleepMode(handle->dma_handle->dma, IfxDma_SleepMode_disable);
    }

#if (DMA_GENERIC_TCX == DMA_GENERIC_TC3)
    if (handle->app_config->source_err_config)
    {
      /* Allow source error reporting for both move engines */
      IfxDma_enableMoveEngineSourceError(handle->dma_handle->dma, IfxDma_MoveEngine_0);
      IfxDma_enableMoveEngineSourceError(handle->dma_handle->dma, IfxDma_MoveEngine_1);
    }
    else
    {
      /* Disable source error reporting for both move engines */
      IfxDma_disableMoveEngineSourceError(handle->dma_handle->dma, IfxDma_MoveEngine_0);
      IfxDma_disableMoveEngineSourceError(handle->dma_handle->dma, IfxDma_MoveEngine_1);
    }

    if (handle->app_config->destination_err_config)
    {
      /* Allow destination error reporting for both move engines */
      IfxDma_enableMoveEngineDestinationError(handle->dma_handle->dma, IfxDma_MoveEngine_0);
      IfxDma_enableMoveEngineDestinationError(handle->dma_handle->dma, IfxDma_MoveEngine_1);
    }
    else
    {
      /* Disable destination error reporting for both move engines */
      IfxDma_disableMoveEngineDestinationError(handle->dma_handle->dma, IfxDma_MoveEngine_0);
      IfxDma_disableMoveEngineDestinationError(handle->dma_handle->dma, IfxDma_MoveEngine_1);
    }

    if (handle->app_config->linked_list_tcs_err_config)
    {
      /* Enable linked-list TCS error reporting for both move engines */
      IfxDma_enableMoveEngineDmaLinkedListError(handle->dma_handle->dma, IfxDma_MoveEngine_0);
      IfxDma_enableMoveEngineDmaLinkedListError(handle->dma_handle->dma, IfxDma_MoveEngine_1);
    }
    else
    {
      /* Disable linked-list TCS error reporting for both move engines */
      IfxDma_disableMoveEngineDmaLinkedListError(handle->dma_handle->dma, IfxDma_MoveEngine_0);
      IfxDma_disableMoveEngineDmaLinkedListError(handle->dma_handle->dma, IfxDma_MoveEngine_1);
    }
#else
    for (int rpIndex = 0; rpIndex < handle->app_config->rp_ch_count; rpIndex++)
    {
      if (handle->app_config->source_err_config_ptr[rpIndex])
      {
        /* RP[rpIndex]: enable source error reporting */
        IfxDma_enableMoveEngineSourceError(handle->dma_handle->dma, rpIndex);
      }
      else
      {
        /* RP[rpIndex]: disable source error reporting */
        IfxDma_disableMoveEngineSourceError(handle->dma_handle->dma, rpIndex);
      }

      if (handle->app_config->destination_err_config_ptr[rpIndex])
      {
        /* RP[rpIndex]: enable destination error reporting */
        IfxDma_enableMoveEngineDestinationError(handle->dma_handle->dma, rpIndex);
      }
      else
      {
        /* RP[rpIndex]: disable destination error reporting */
        IfxDma_disableMoveEngineDestinationError(handle->dma_handle->dma, rpIndex);
      }

      if (handle->app_config->ll_tcs_err_config_ptr[rpIndex])
      {
        /* RP[rpIndex]: enable linked-list TCS error (ELER) */
        handle->dma_handle->dma->RP[rpIndex].EER.B.ELER = TRUE;
      }
      else
      {
        /* RP[rpIndex]: disable linked-list TCS error (ELER) */
        handle->dma_handle->dma->RP[rpIndex].EER.B.ELER = FALSE;
      }

      if (handle->app_config->ch_disable_trl_err_config_ptr[rpIndex])
      {
        /* RP[rpIndex]: enable channel-disable TRL error (ECDTER) */
        handle->dma_handle->dma->RP[rpIndex].EER.B.ECDTER = TRUE;
      }
      else
      {
        /* RP[rpIndex]: disable channel-disable TRL error (ECDTER) */
        handle->dma_handle->dma->RP[rpIndex].EER.B.ECDTER = FALSE;
      }
    }
#endif
  }
  else
  {
    /* Do Nothing */
  }

  return DMA_GENERIC_STATUS_SUCCESS;
}

